// Spec function to describe starts_with relation (conceptual, for documentation)
fn starts_with(s: &[char], p: &[char]) -> bool {
    if p.is_empty() {
        true
    } else if s.len() < p.len() {
        false
    } else {
        s.iter().zip(p.iter()).all(|(sc, pc)| sc == pc)
    }
}

// Check if vector v has prefix p
fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    starts_with(v.as_slice(), p.as_slice())
}

// Filter sequences by prefix p
fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    xs.into_iter()
        .filter(|v| has_prefix(v, &p))
        .collect()
}